  async queryCatalogCandidates(input: CatalogCandidateQueryInput) {
    if (input.availabilityMode === "unavailable") return [];
    const result = await this.service.queryCandidates({
      serviceDate: "2000-01-01",
      serviceLanguage: input.serviceLanguage,
      ...(input.organistPersonId ? { organistPersonId: input.organistPersonId } : {}),
      ...(input.referenceAntiphonId ? { referenceAntiphonId: input.referenceAntiphonId } : {}),
      ...(input.referenceTopicId ? { referenceTopicId: input.referenceTopicId } : {}),
      ...(input.queryText !== undefined ? { queryText: input.queryText } : {}),
      candidateUsages: [],
    });
    return result.success ? applyMemoryTopicSignal(result.value, input.referenceTopicId) : [];
  }
  async hydrateCandidates(input: CandidateHydrationClientInput) {
    const result = await this.service.hydrateCandidates(input);
    return result.success ? applyMemoryTopicSignal(result.value, input.referenceTopicId) : [];
  }
}

const memoryTopicProvider = new MemoryReferenceThematicSectionProvider();
async function applyMemoryTopicSignal(candidates: CandidateQueryResult[], referenceTopicId?: string): Promise<CandidateQueryResult[]> {
  if (!referenceTopicId) return candidates;
  const topic = await memoryTopicProvider.getSectionById(referenceTopicId);
  if (!topic) return candidates.map((candidate) => ({ ...candidate, seasonMatch: false, signal: candidate.antiphonMatch ? "antiphon" : "none" }));
  return candidates.map((candidate) => {
    const base = candidateBaseNumber(candidate.number);
    const seasonMatch = candidate.language === topic.language && base !== undefined && topic.ranges.some((range) => base >= range.from && base <= range.to);
    return { ...candidate, seasonMatch, signal: candidate.antiphonMatch ? "antiphon" : seasonMatch ? "season" : "none" };
  });
}
function candidateBaseNumber(value: string): number | undefined {
  const match = value.match(/^([1-9]\d*)(?:\/\d+)?$/);
  return match ? Number(match[1]) : undefined;
}

export class DbCatalogClient {
  async getPerson(input: { id: string }) { return callCatalogApi("getPerson", input); }
  async getSong(input: { songId: string }) { return callCatalogApi("getSong", input); }
  async getSongs(input: { songIds: string[] }) { return callCatalogApi("getSongs", input); }
  async getPlanningPeople() { return callCatalogApi("getPlanningPeople", {}); }
  async searchPeople(input: { role: PersonRole; query?: string }) { return callCatalogApi("searchPeople", input); }
  async listPeople() { return callCatalogApi("listPeople", {}); }
  async savePerson(input: { role: PlanningRole; actorUserId?: string; person: Omit<CatalogPerson, "id"> & { id?: string } }) { return callCatalogApi("savePerson", input, input.actorUserId ? { userId: input.actorUserId, role: input.role } : undefined); }
  async searchSongs(input: { language: ServiceLanguage; query?: string }) { return callCatalogApi("searchSongs", input); }
  async listSongs() { return callCatalogApi("listSongs", {}); }
  async setSongActive(input: { role: PlanningRole; actorUserId?: string; songId: string; active: boolean }) { return callCatalogApi("setSongActive", input, input.actorUserId ? { userId: input.actorUserId, role: input.role } : undefined); }
}

type LocalActorRequest = { userId: string; role?: PlanningRole };
function protectedActorEnvelope(actor?: LocalActorRequest) { return actor ? { actor: { ...(actor.role ? { role: actor.role } : {}) } } : {}; }
async function callInteractionApi(action: string, input: unknown, actor?: LocalActorRequest) {
  const response = await fetch("/api/interaction", { method: "POST", headers: jsonHeaders, body: JSON.stringify({ action, input, ...protectedActorEnvelope(actor) }) });
  const payload = await response.json();
  if (!response.ok) return apiFailure(payload, "Interaction API request failed.");
  return payload;
}

async function callCatalogApi(action: string, input: unknown, actor?: LocalActorRequest) {
  const response = await fetch("/api/catalog", { method: "POST", headers: jsonHeaders, body: JSON.stringify({ action, input, ...protectedActorEnvelope(actor) }) });
  const payload = await response.json();
  if (!response.ok) return apiFailure(payload, "Catalog API request failed.");
  return payload;
}

async function callPlanningLifecycleApi(action: string, input: unknown, actor?: LocalActorRequest) {
  const response = await fetch("/api/planning-lifecycle", {
    method: "POST",
    headers: jsonHeaders,
    body: JSON.stringify({ action, input, ...protectedActorEnvelope(actor) }),
  });

  const payload = await response.json();

  if (!response.ok) {
    return apiFailure(payload, "Planning Lifecycle API request failed.");
  }

  return payload;
}

const jsonHeaders = { "content-type": "application/json" };
function actorContextFrom(input: unknown): LocalActorRequest | undefined { if (typeof input !== "object" || input === null || !("localActorUserId" in input)) return undefined; const value = input as { localActorUserId?: unknown; role?: unknown }; return typeof value.localActorUserId === "string" ? { userId: value.localActorUserId, ...(typeof value.role === "string" ? { role: value.role as PlanningRole } : {}) } : undefined; }

"use client";

import { FormEvent, useEffect, useState } from "react";
import type { PersistedPlanningPlan } from "../src/application/planning-lifecycle";
import { WHATSAPP_PHONE_CHANGED_EVENT, normalizeWhatsAppPhone } from "../src/application/whatsapp-phone";
import { buildFinalPlanWhatsAppUrl } from "../src/planning-lifecycle/whatsapp-finalization";
import type { RuntimeMode } from "./planning-lifecycle-client";

type Props = {
  plan: PersistedPlanningPlan;
  runtimeMode: RuntimeMode;
  onClose: () => void;
};

export function PostFinalizeWhatsAppHandoff({ plan, runtimeMode, onClose }: Props) {
  const [phone, setPhone] = useState<string | null>(null);
  const [loadingPhone, setLoadingPhone] = useState(runtimeMode === "db");
  const [phonePromptOpen, setPhonePromptOpen] = useState(false);
  const [phoneInput, setPhoneInput] = useState("");
  const [rememberPhone, setRememberPhone] = useState(false);
  const [phoneError, setPhoneError] = useState<string | null>(null);
  const [savingPhone, setSavingPhone] = useState(false);

  useEffect(() => {
    function handlePhoneChange(event: Event) {
      const value = (event as CustomEvent<unknown>).detail;
      setPhone(typeof value === "string" && value ? value : null);
    }
    window.addEventListener(WHATSAPP_PHONE_CHANGED_EVENT, handlePhoneChange);
    return () => window.removeEventListener(WHATSAPP_PHONE_CHANGED_EVENT, handlePhoneChange);
  }, []);

  useEffect(() => {
    if (runtimeMode !== "db") {
      setLoadingPhone(false);
      return;
    }
    let cancelled = false;
    void fetch("/api/account/whatsapp-phone", { method: "GET", cache: "no-store" })
      .then(async (response) => {
        if (!response.ok) throw new Error("Saved WhatsApp phone could not be loaded.");
        return response.json() as Promise<{ phoneE164?: string | null }>;
      })
      .then((result) => {
        if (!cancelled) setPhone(result.phoneE164 ?? null);
      })
      .catch(() => {
        if (!cancelled) setPhone(null);
      })
      .finally(() => {
        if (!cancelled) setLoadingPhone(false);
      });
    return () => { cancelled = true; };
  }, [runtimeMode]);

  function openPhonePrompt() {
    setPhoneInput(phone ?? "");
    setRememberPhone(false);
    setPhoneError(null);
    setPhonePromptOpen(true);
  }

  function openOneTime(phoneE164: string) {
    window.open(buildFinalPlanWhatsAppUrl(plan, phoneE164), "_blank", "noopener,noreferrer");
    onClose();
  }

  async function submitPhone(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setPhoneError(null);
    let phoneE164: string;
    try { phoneE164 = normalizeWhatsAppPhone(phoneInput); }
    catch (error) {
      setPhoneError(error instanceof Error ? error.message : "Phone number is invalid.");
      return;
    }

    if (!rememberPhone || runtimeMode !== "db") {
      openOneTime(phoneE164);
      return;
    }

    const popup = window.open("about:blank", "_blank");
    if (popup) popup.opener = null;
    setSavingPhone(true);
    try {
      const response = await fetch("/api/account/whatsapp-phone", {
        method: "PUT",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ phone: phoneE164 }),
      });
      const payload = await response.json().catch(() => undefined) as { phoneE164?: string; error?: { message?: string } } | undefined;
      if (!response.ok || !payload?.phoneE164) {
        popup?.close();
        setPhoneError(payload?.error?.message ?? "WhatsApp phone could not be saved.");
        return;
      }
      setPhone(payload.phoneE164);
      window.dispatchEvent(new CustomEvent(WHATSAPP_PHONE_CHANGED_EVENT, { detail: payload.phoneE164 }));
      const target = buildFinalPlanWhatsAppUrl(plan, payload.phoneE164);
      if (popup) popup.location.href = target;
      else window.open(target, "_blank", "noopener,noreferrer");
      onClose();
    } catch {
      popup?.close();
      setPhoneError("WhatsApp phone could not be saved.");
    } finally {
      setSavingPhone(false);
    }
  }

  if (phonePromptOpen) {
    return (
      <div className="post-finalize-dialog-backdrop" role="presentation">
        <section className="post-finalize-dialog" role="dialog" aria-modal="true" aria-labelledby="whatsapp-phone-dialog-title">
          <h2 id="whatsapp-phone-dialog-title">WhatsApp phone</h2>
          <p>Enter the phone number that WhatsApp should open for this finalized plan.</p>
          <p className="field-help">If you save it, the number is stored with your protected Account and future WhatsApp handoffs will use it automatically. You can later change or forget it in User → Phone Setting.</p>
          <form className="planning-form" onSubmit={submitPhone}>
            <label>
              Phone number
              <input
                type="tel"
                inputMode="tel"
                autoComplete="tel"
                value={phoneInput}
                onChange={(event) => setPhoneInput(event.target.value)}
                placeholder="+420 601 234 567"
                required
              />
            </label>
            {runtimeMode === "db" && (
              <label>
                <input type="checkbox" checked={rememberPhone} onChange={(event) => setRememberPhone(event.target.checked)} />
                {" "}Save this number to my protected Account and use it automatically next time
              </label>
            )}
            {phoneError && <p className="auth-error" role="alert">{phoneError}</p>}
            <div className="post-finalize-dialog-actions">
              <button type="submit" disabled={savingPhone}>{savingPhone ? "Saving…" : "Open WhatsApp"}</button>
              <button type="button" disabled={savingPhone} onClick={() => { setPhonePromptOpen(false); setPhoneError(null); }}>Back</button>
            </div>
          </form>
        </section>
      </div>
    );
  }

  return (
    <div className="post-finalize-dialog-backdrop" role="presentation">
      <section className="post-finalize-dialog" role="dialog" aria-modal="true" aria-labelledby="post-finalize-dialog-title">
        <h2 id="post-finalize-dialog-title">Plan finalized</h2>
        <p>Inform about the finalized plan via WhatsApp?</p>
        <div className="post-finalize-dialog-actions">
          {phone ? (
            <a href={buildFinalPlanWhatsAppUrl(plan, phone)} target="_blank" rel="noopener noreferrer" onClick={onClose}>
              Open WhatsApp
            </a>
          ) : (
            <button type="button" onClick={openPhonePrompt} disabled={loadingPhone}>
              {loadingPhone ? "Loading…" : "Open WhatsApp"}
            </button>
          )}
          <button type="button" onClick={onClose}>Close</button>
        </div>
      </section>
    </div>
  );
}

"use client";

import { FormEvent, useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import type { PlanningRole } from "../src/planning-lifecycle";
import { ACTIVE_ROLE_CHANGED_EVENT, isPlanningRole, serializeActiveRoleCookie } from "../src/application/active-role";
import { authClient } from "../src/auth/client";
import { PasswordVisibilityField } from "./password-visibility-field";
import { ProtectedWhatsAppPhoneSetting } from "./protected-whatsapp-phone-setting";
import { GuideHintsSetting } from "./guide-hints-setting";

type PendingAccountAction = "signOut" | "changePassword" | null;

const VERIFY_DB_COMMAND = 'cd "$env:LOCALAPPDATA\\Organy\\verify-db"\nnpm run db:verify:offline';

type TrackedButtonState = {
  button: HTMLButtonElement;
  originalDisabled: boolean;
  originalText: string;
  requests: number;
  releaseTimer: number | null;
};

function processingLabel(label: string): string {
  const normalized = label.trim().toLowerCase();
  if (normalized.startsWith("save")) return "Saving…";
  if (normalized.startsWith("finalize")) return "Finalizing…";
  if (normalized.startsWith("complete")) return "Completing…";
  if (normalized.startsWith("delete")) return "Deleting…";
  if (normalized.startsWith("reopen")) return "Reopening…";
  if (normalized.startsWith("edit")) return "Opening…";
  if (normalized.startsWith("store")) return "Storing…";
  if (normalized.startsWith("refresh")) return "Refreshing…";
  if (normalized.startsWith("merge")) return "Merging…";
  if (normalized.startsWith("add")) return "Adding…";
  if (normalized.startsWith("remove")) return "Removing…";
  if (normalized.startsWith("toggle")) return "Updating…";
  if (normalized.startsWith("mark")) return "Updating…";
  if (normalized.startsWith("set")) return "Saving…";
  return "Processing…";
}

function formatRole(role: PlanningRole): string {
  return `${role.slice(0, 1).toUpperCase()}${role.slice(1)}`;
}

export function ProtectedAccountControls({ displayName, roles, initialActiveRole, initialWhatsAppPhone }: { displayName: string; roles: string[]; initialActiveRole: PlanningRole; initialWhatsAppPhone?: string }) {
  const [portalTarget, setPortalTarget] = useState<HTMLElement | null>(null);
  const [editingPassword, setEditingPassword] = useState(false);
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [feedback, setFeedback] = useState<string | null>(null);
  const [pendingAction, setPendingAction] = useState<PendingAccountAction>(null);
  const [verifyDbOpen, setVerifyDbOpen] = useState(false);
  const [verifyDbCopied, setVerifyDbCopied] = useState(false);
  const [activeRole, setActiveRole] = useState<PlanningRole>(initialActiveRole);
  const userMenuRef = useRef<HTMLDetailsElement>(null);
  const signRoleMenuRef = useRef<HTMLDetailsElement>(null);
  const roleMenuRef = useRef<HTMLDetailsElement>(null);

  function resetPasswordEditor() {
    setEditingPassword(false);
    setCurrentPassword("");
    setNewPassword("");
    setFeedback(null);
  }

  function closeUserMenu() {
    if (userMenuRef.current) userMenuRef.current.open = false;
    if (signRoleMenuRef.current) signRoleMenuRef.current.open = false;
    resetPasswordEditor();
  }

  function closeRoleMenu() {
    if (roleMenuRef.current) roleMenuRef.current.open = false;
  }

  useEffect(() => {
    let frame = 0;
    let attachedHeader: HTMLElement | null = null;
    let previousTabIndex: string | null = null;
    let previousDescribedBy: string | null = null;
    let helper: HTMLElement | null = null;
    let helperHadId = false;
    let titleArea: HTMLElement | null = null;
    let titleTapHandler: ((event: MouseEvent) => void) | null = null;

    function attachToWorkspaceHeader() {
      const header = document.querySelector<HTMLElement>(".app-header");
      if (!header) {
        frame = window.requestAnimationFrame(attachToWorkspaceHeader);
        return;
      }

      attachedHeader = header;
      previousTabIndex = header.getAttribute("tabindex");
      previousDescribedBy = header.getAttribute("aria-describedby");
      helper = header.querySelector<HTMLElement>(".lede");
      helperHadId = Boolean(helper?.id);
      if (helper && !helper.id) helper.id = "workspace-helper-copy";
      header.tabIndex = 0;
      if (helper?.id) header.setAttribute("aria-describedby", helper.id);

      if (header.firstElementChild instanceof HTMLElement) {
        titleArea = header.firstElementChild;
        titleTapHandler = (event: MouseEvent) => {
          const target = event.target instanceof Element ? event.target : null;
          if (target?.closest("a, button, input, select, textarea, summary, details")) return;
          header.focus();
        };
        titleArea.addEventListener("click", titleTapHandler);
      }

      setPortalTarget(header);
    }

    attachToWorkspaceHeader();

    return () => {
      window.cancelAnimationFrame(frame);
      if (titleArea && titleTapHandler) titleArea.removeEventListener("click", titleTapHandler);
      if (!attachedHeader) return;
      if (previousTabIndex === null) attachedHeader.removeAttribute("tabindex");
      else attachedHeader.setAttribute("tabindex", previousTabIndex);
      if (previousDescribedBy === null) attachedHeader.removeAttribute("aria-describedby");
      else attachedHeader.setAttribute("aria-describedby", previousDescribedBy);
      if (helper && !helperHadId && helper.id === "workspace-helper-copy") helper.removeAttribute("id");
    };
  }, []);

  useEffect(() => {
    function handleActiveRoleChange(event: Event) {
      const role = (event as CustomEvent<unknown>).detail;
      if (isPlanningRole(role) && roles.includes(role)) setActiveRole(role);
    }
    window.addEventListener(ACTIVE_ROLE_CHANGED_EVENT, handleActiveRoleChange);
    return () => window.removeEventListener(ACTIVE_ROLE_CHANGED_EVENT, handleActiveRoleChange);
  }, [roles]);

  useEffect(() => {
    function handlePointerDown(event: PointerEvent) {
      const target = event.target instanceof Element ? event.target : null;
      if (!target) return;

      if (userMenuRef.current?.contains(target)) {
        closeRoleMenu();
        return;
      }

      if (roleMenuRef.current?.contains(target)) {
        closeUserMenu();
        return;
      }

      closeUserMenu();
      closeRoleMenu();
    }

    function handleKeyDown(event: KeyboardEvent) {
      if (event.key !== "Escape") return;
      setVerifyDbOpen(false);
      setVerifyDbCopied(false);
      closeUserMenu();
      closeRoleMenu();
    }

    document.addEventListener("pointerdown", handlePointerDown, true);
    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("pointerdown", handlePointerDown, true);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, []);

  useEffect(() => {
    const originalFetch = window.fetch.bind(window) as typeof window.fetch;
    let armedButton: HTMLButtonElement | null = null;
    let active: TrackedButtonState | null = null;

    function clearActive(expected: TrackedButtonState) {
      if (active !== expected || expected.requests !== 0) return;
      if (expected.releaseTimer !== null) window.clearTimeout(expected.releaseTimer);
      if (expected.button.isConnected) {
        expected.button.disabled = expected.originalDisabled;
        expected.button.removeAttribute("aria-busy");
        expected.button.classList.remove("workspace-action-pending");
        expected.button.textContent = expected.originalText;
      }
      active = null;
    }

    function scheduleRelease(state: TrackedButtonState) {
      if (state.releaseTimer !== null) window.clearTimeout(state.releaseTimer);
      state.releaseTimer = window.setTimeout(() => clearActive(state), 60);
    }

    function begin(button: HTMLButtonElement): TrackedButtonState {
      if (active?.button === button) {
        if (active.releaseTimer !== null) {
          window.clearTimeout(active.releaseTimer);
          active.releaseTimer = null;
        }
        return active;
      }
      if (active && active.requests === 0) clearActive(active);
      const state: TrackedButtonState = {
        button,
        originalDisabled: button.disabled,
        originalText: button.textContent ?? "",
        requests: 0,
        releaseTimer: null,
      };
      button.disabled = true;
      button.setAttribute("aria-busy", "true");
      button.classList.add("workspace-action-pending");
      button.textContent = processingLabel(state.originalText);
      active = state;
      return state;
    }

    const trackedFetch: typeof window.fetch = async (...args) => {
      const button = armedButton ?? active?.button ?? null;
      if (!button) return originalFetch(...args);
      const state = begin(button);
      armedButton = null;
      state.requests += 1;
      try {
        return await originalFetch(...args);
      } finally {
        state.requests -= 1;
        if (state.requests === 0) scheduleRelease(state);
      }
    };

    function captureWorkspaceAction(event: MouseEvent) {
      const target = event.target instanceof Element ? event.target : null;
      const button = target?.closest<HTMLButtonElement>("button") ?? null;
      if (!button || button.disabled || button.closest(".workspace-account-panel")) return;
      if (!button.closest(".planning-card .form-actions, .planning-card .db-workspace")) return;
      armedButton = button;
      window.setTimeout(() => {
        if (armedButton === button) armedButton = null;
      }, 0);
    }

    document.addEventListener("click", captureWorkspaceAction, true);
    window.fetch = trackedFetch;

    return () => {
      document.removeEventListener("click", captureWorkspaceAction, true);
      if (window.fetch === trackedFetch) window.fetch = originalFetch;
      if (active) {
        active.requests = 0;
        clearActive(active);
      }
    };
  }, []);

  function selectSignedInRole(role: PlanningRole) {
    if (!roles.includes(role)) return;
    document.cookie = serializeActiveRoleCookie(role);
    setActiveRole(role);
    setVerifyDbOpen(false);
    setVerifyDbCopied(false);
    window.dispatchEvent(new CustomEvent(ACTIVE_ROLE_CHANGED_EVENT, { detail: role }));
    closeUserMenu();
  }

  async function copyVerifyDbCommand() {
    try {
      await navigator.clipboard.writeText(VERIFY_DB_COMMAND);
      setVerifyDbCopied(true);
    } catch {
      setVerifyDbCopied(false);
    }
  }

  async function signOut() {
    if (pendingAction) return;
    setFeedback(null);
    setPendingAction("signOut");
    try {
      await authClient.signOut();
      window.location.assign("/sign-in");
    } finally {
      setPendingAction(null);
    }
  }

  async function changePassword(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (pendingAction) return;
    setFeedback(null);
    setPendingAction("changePassword");
    try {
      const result = await authClient.changePassword({ currentPassword, newPassword, revokeOtherSessions: true });
      if (result.error) {
        setFeedback("Password change failed. Check the current password and the new password requirements.");
        return;
      }
      setCurrentPassword("");
      setNewPassword("");
      setEditingPassword(false);
      setFeedback("Password changed.");
    } catch {
      setFeedback("Password change failed.");
    } finally {
      setPendingAction(null);
    }
  }

  const assignedRoles = roles.filter(isPlanningRole);
  const activeAdmin = activeRole === "admin" && roles.includes("admin");
  const pending = pendingAction !== null;

  if (!portalTarget) return null;

  return createPortal(
    <div className="workspace-account-panel" aria-label="Signed-in account">
      <details
        className="workspace-account-menu"
        ref={userMenuRef}
        onToggle={(event) => {
          if (event.currentTarget.open) closeRoleMenu();
          else resetPasswordEditor();
        }}
      >
        <summary>
          <span>User <strong>{displayName}</strong></span>
          <span className="workspace-menu-dots" aria-hidden="true">⋯</span>
        </summary>
        <div className="workspace-account-popover">
          {!editingPassword ? (
            <>
              <details className="workspace-sign-role-menu" ref={signRoleMenuRef}>
                <summary>
                  <span>Sign Role</span>
                  <span className="workspace-sign-role-arrow" aria-hidden="true" />
                </summary>
                <div className="workspace-sign-role-options" aria-label="Assigned roles">
                  {assignedRoles.map((role) => (
                    <button
                      type="button"
                      key={role}
                      aria-current={role === activeRole ? "true" : undefined}
                      onClick={() => selectSignedInRole(role)}
                    >
                      {formatRole(role)}
                    </button>
                  ))}
                </div>
              </details>
              <GuideHintsSetting />
              <ProtectedWhatsAppPhoneSetting initialPhone={initialWhatsAppPhone} roles={roles} />
              <button type="button" onClick={() => { setEditingPassword(true); setFeedback(null); }} disabled={pending}>Change Password</button>
              <button type="button" onClick={signOut} disabled={pending} aria-busy={pendingAction === "signOut"}>{pendingAction === "signOut" ? "Signing Out…" : "Sign Out"}</button>
            </>
          ) : (
            <form className="workspace-password-form" onSubmit={changePassword}>
              <PasswordVisibilityField id="current-account-password" label="Current password" autoComplete="current-password" value={currentPassword} onChange={(event) => setCurrentPassword(event.target.value)} required />
              <PasswordVisibilityField id="new-account-password" label="New password" autoComplete="new-password" value={newPassword} onChange={(event) => setNewPassword(event.target.value)} minLength={8} required />
              <div className="workspace-account-actions">
                <button type="submit" disabled={pending} aria-busy={pendingAction === "changePassword"}>{pendingAction === "changePassword" ? "Saving…" : "Save"}</button>
                <button type="button" disabled={pending} onClick={resetPasswordEditor}>Cancel</button>
              </div>
            </form>
          )}
          {feedback && <span className="workspace-account-feedback" role="status">{feedback}</span>}
        </div>
      </details>

      {activeAdmin ? (
        <details
          className="workspace-account-menu workspace-role-menu"
          ref={roleMenuRef}
          onToggle={(event) => {
            if (event.currentTarget.open) closeUserMenu();
          }}
        >
          <summary>
            <span>Role <strong>Admin</strong></span>
            <span className="workspace-menu-dots" aria-hidden="true">⋯</span>
          </summary>
          <div className="workspace-account-popover">
            <a href="/admin/accounts">Manage Accounts</a>
            <a href="/admin/audit-history">Audit History</a>
            <button
              type="button"
              onClick={() => {
                setVerifyDbCopied(false);
                setVerifyDbOpen(true);
                closeRoleMenu();
              }}
            >
              Verify DB
            </button>
          </div>
        </details>
      ) : (
        <span className="workspace-role-label">Role <strong>{formatRole(activeRole)}</strong></span>
      )}

      {activeAdmin && verifyDbOpen && (
        <div className="verify-db-dialog-backdrop" role="presentation">
          <section className="verify-db-dialog" role="dialog" aria-modal="true" aria-labelledby="verify-db-dialog-title">
            <h2 id="verify-db-dialog-title">Verify DB</h2>
            <p>Create a fresh complete copy of the current Production database for local SQL verification.</p>
            <p><strong>Safety:</strong> Production → backup → local offline database. Nothing is restored or synchronized back to Production.</p>
            <ol>
              <li>Open PowerShell.</li>
              <li>Copy the complete block below, paste it into PowerShell, and press Enter.</li>
              <li>When recovery checks pass, the local Pgweb SQL editor opens automatically on the disposable database.</li>
            </ol>
            <pre className="verify-db-command"><code>{VERIFY_DB_COMMAND}</code></pre>
            <div className="verify-db-dialog-actions">
              <button type="button" onClick={copyVerifyDbCommand}>{verifyDbCopied ? "Copied" : "Copy PowerShell block"}</button>
              <button type="button" onClick={() => { setVerifyDbOpen(false); setVerifyDbCopied(false); }}>Close</button>
            </div>
            <p className="verify-db-dialog-note">Each run replaces only the dedicated offline database. Timestamped backup artifacts remain under the Git-ignored <code>.organy-backups</code> folder.</p>
          </section>
        </div>
      )}
    </div>,
    portalTarget,
  );
}

"use client";

import { FormEvent, useEffect, useState } from "react";
import { WHATSAPP_PHONE_CHANGED_EVENT, canOwnWhatsAppPhone, normalizeWhatsAppPhone } from "../src/application/whatsapp-phone";

export function ProtectedWhatsAppPhoneSetting({ initialPhone, roles }: { initialPhone?: string; roles: string[] }) {
  const [phone, setPhone] = useState(initialPhone ?? "");
  const [open, setOpen] = useState(false);
  const [input, setInput] = useState(initialPhone ?? "");
  const [pending, setPending] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);

  useEffect(() => {
    if (!open) return;
    function handleEscape(event: KeyboardEvent) {
      if (event.key === "Escape") {
        setOpen(false);
        setFeedback(null);
      }
    }
    document.addEventListener("keydown", handleEscape);
    return () => document.removeEventListener("keydown", handleEscape);
  }, [open]);

  useEffect(() => {
    function handlePhoneChange(event: Event) {
      const value = (event as CustomEvent<unknown>).detail;
      const next = typeof value === "string" ? value : "";
      setPhone(next);
      if (next) setInput(next);
      else setOpen(false);
    }
    window.addEventListener(WHATSAPP_PHONE_CHANGED_EVENT, handlePhoneChange);
    return () => window.removeEventListener(WHATSAPP_PHONE_CHANGED_EVENT, handlePhoneChange);
  }, []);

  if (!phone || !canOwnWhatsAppPhone(roles)) return null;

  async function save(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setFeedback(null);
    let normalized: string;
    try { normalized = normalizeWhatsAppPhone(input); }
    catch (error) {
      setFeedback(error instanceof Error ? error.message : "Phone number is invalid.");
      return;
    }

    setPending(true);
    try {
      const response = await fetch("/api/account/whatsapp-phone", {
        method: "PUT",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ phone: normalized }),
      });
      const payload = await response.json().catch(() => undefined) as { phoneE164?: string; error?: { message?: string } } | undefined;
      if (!response.ok || !payload?.phoneE164) {
        setFeedback(payload?.error?.message ?? "WhatsApp phone could not be saved.");
        return;
      }
      setPhone(payload.phoneE164);
      setInput(payload.phoneE164);
      setOpen(false);
      window.dispatchEvent(new CustomEvent(WHATSAPP_PHONE_CHANGED_EVENT, { detail: payload.phoneE164 }));
    } catch {
      setFeedback("WhatsApp phone could not be saved.");
    } finally { setPending(false); }
  }

  async function forget() {
    if (!window.confirm("Forget this WhatsApp phone and revoke automatic use?")) return;
    setPending(true);
    setFeedback(null);
    try {
      const response = await fetch("/api/account/whatsapp-phone", { method: "DELETE" });
      const payload = await response.json().catch(() => undefined) as { error?: { message?: string } } | undefined;
      if (!response.ok) {
        setFeedback(payload?.error?.message ?? "WhatsApp phone could not be forgotten.");
        return;
      }
      setPhone("");
      setInput("");
      setOpen(false);
      window.dispatchEvent(new CustomEvent(WHATSAPP_PHONE_CHANGED_EVENT, { detail: null }));
    } catch {
      setFeedback("WhatsApp phone could not be forgotten.");
    } finally { setPending(false); }
  }

  return (
    <>
      <button type="button" onClick={() => { setInput(phone); setFeedback(null); setOpen(true); }}>Phone Setting</button>
      {open && (
        <div className="post-finalize-dialog-backdrop" role="presentation">
          <section className="post-finalize-dialog" role="dialog" aria-modal="true" aria-labelledby="phone-setting-dialog-title">
            <h2 id="phone-setting-dialog-title">Phone Setting</h2>
            <p>This number is saved to your protected Account and is used to open WhatsApp after you finalize a plan.</p>
            <form className="planning-form" onSubmit={save}>
              <label>
                Phone number
                <input type="tel" inputMode="tel" autoComplete="tel" value={input} onChange={(event) => setInput(event.target.value)} required />
              </label>
              {feedback && <p className="auth-error" role="alert">{feedback}</p>}
              <div className="post-finalize-dialog-actions">
                <button type="submit" disabled={pending}>{pending ? "Saving…" : "Save"}</button>
                <button type="button" disabled={pending} onClick={forget}>Forget Phone</button>
                <button type="button" disabled={pending} onClick={() => { setOpen(false); setFeedback(null); }}>Cancel</button>
              </div>
            </form>
          </section>
        </div>
      )}
    </>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { DbReferenceAntiphonClient } from "../src/application/reference-antiphon-client";
import type { ReferenceAntiphonRecord } from "../src/application/reference-antiphon-contract";
import { DbReferenceAntiphonRecommendationClient, type ReferenceAntiphonRecommendationActor } from "../src/application/reference-antiphon-recommendation-client";
import { DbReferenceCatalogClient } from "../src/application/reference-catalog-client";
import type { ReferenceCatalogRecord } from "../src/application/reference-catalog-contract";
import {
  ReferenceAntiphonRecommendationUiState,
  type RecommendationUiRole,
  type RecommendationUiSnapshot,
} from "../src/application/reference-antiphon-recommendation-ui-state";

export type RecommendationPanelClients = {
  antiphons: Pick<DbReferenceAntiphonClient, "list">;
  catalog: Pick<DbReferenceCatalogClient, "list">;
  recommendations: Pick<DbReferenceAntiphonRecommendationClient, "get" | "set">;
};
export type RecommendationPanelClientFactories = {
  antiphons: () => RecommendationPanelClients["antiphons"];
  catalog: () => RecommendationPanelClients["catalog"];
  recommendations: (actor: ReferenceAntiphonRecommendationActor) => RecommendationPanelClients["recommendations"];
};
const defaultFactories: RecommendationPanelClientFactories = {
  antiphons: () => new DbReferenceAntiphonClient(),
  catalog: () => new DbReferenceCatalogClient(),
  recommendations: (actor) => new DbReferenceAntiphonRecommendationClient(actor),
};
export function createRecommendationPanelClients(runtime: "memory" | "db", actor: ReferenceAntiphonRecommendationActor, factories = defaultFactories): RecommendationPanelClients | null {
  if (runtime === "memory") return null;
  const recommendationActor: ReferenceAntiphonRecommendationActor = { userId: actor.userId, role: actor.role };
  return { antiphons: factories.antiphons(), catalog: factories.catalog(), recommendations: factories.recommendations(recommendationActor) };
}

export type ReferenceAntiphonRecommendationPanelProps = {
  runtime: "memory" | "db";
  actor: ReferenceAntiphonRecommendationActor;
  clientFactories?: RecommendationPanelClientFactories;
};

type ViewProps = {
  runtime: "memory" | "db"; role: RecommendationUiRole; snapshot: RecommendationUiSnapshot;
  antiphonSearch: string; songSearch: string;
  setAntiphonSearch: (value: string) => void; setSongSearch: (value: string) => void;
  chooseAntiphon: (record: ReferenceAntiphonRecord) => void; deselectAntiphon: () => void;
  chooseSong: (record: ReferenceCatalogRecord) => void; mutate: (referenceSongId: string | null) => void;
};

export function ReferenceAntiphonRecommendationPanelView(props: ViewProps) {
  const { runtime, role, snapshot: s } = props;
  if (runtime === "memory") return <section className="detail-panel" aria-label="Reference antiphon recommendation"><h2>Antiphon recommendation</h2><p className="field-help">Antiphon recommendations are available only in DB runtime.</p></section>;
  const selected = s.selectedAntiphon;
  const read = s.requests.recommendationRead;
  const mutation = s.requests.mutation;
  const currentSong = s.recommendation?.recommendedSong ?? null;
  const sameSong = Boolean(currentSong && s.selectedSong?.id === currentSong.referenceSongId);
  const mutationDisabled = mutation.loading;
  return <section className="detail-panel" aria-label="Reference antiphon recommendation">
    <h2>Antiphon recommendation</h2>
    <label>Find antiphon<input aria-label="Reference antiphon search" value={props.antiphonSearch} onChange={(event) => props.setAntiphonSearch(event.target.value)} placeholder="Search by title or number" /></label>
    {s.requests.antiphonSearch.loading && <p role="status" className="field-help">Loading antiphons…</p>}
    {s.requests.antiphonSearch.error && <p role="alert" className="field-help">Antiphon search unavailable: {s.requests.antiphonSearch.error}</p>}
    {props.antiphonSearch.trim() && !s.requests.antiphonSearch.loading && !s.requests.antiphonSearch.error && s.antiphons.length === 0 && <p className="field-help">No antiphons match this search.</p>}
    <ul className="saved-set-list catalog-song-list">{s.antiphons.map((record) => <li key={record.id}><button type="button" onClick={() => props.chooseAntiphon(record)}>{record.displayNumber} · {record.title}</button></li>)}</ul>
    {!selected ? <p>No antiphon selected</p> : <div aria-label="Selected reference antiphon">
      <h3>{selected.displayNumber} · {selected.title}</h3>
      <button type="button" onClick={props.deselectAntiphon}>Clear antiphon selection</button>
      {(read.loading || (!s.recommendation && !read.error)) && <p role="status" className="field-help">Loading recommendation…</p>}
      {read.error && <p role="alert" className="field-help">Recommendation unavailable: {read.error}</p>}
      {s.recommendation && !currentSong && <p>No recommended song</p>}
      {currentSong && <div aria-label="Recommended Reference song">
        <p><strong>{currentSong.displayNumber} · {currentSong.title}</strong></p>
        <dl><dt>language</dt><dd>{currentSong.language}</dd><dt>canonicalNumber</dt><dd>{currentSong.canonicalNumber}</dd><dt>referenceSongId</dt><dd>{currentSong.referenceSongId}</dd></dl>
      </div>}
      {role === "admin" && s.recommendation && <div aria-label="Manage antiphon recommendation">
        <label>Find Reference song<input aria-label="Recommended Reference song search" value={props.songSearch} disabled={mutationDisabled} onChange={(event) => props.setSongSearch(event.target.value)} /></label>
        {s.requests.songSearch.loading && <p role="status" className="field-help">Loading Reference songs…</p>}
        {s.requests.songSearch.error && <p role="alert" className="field-help">Reference song search unavailable: {s.requests.songSearch.error}</p>}
        {props.songSearch.trim() && !s.requests.songSearch.loading && !s.requests.songSearch.error && s.songs.length === 0 && <p className="field-help">No Reference songs match this search.</p>}
        <ul className="saved-set-list catalog-song-list">{s.songs.map((record) => <li key={record.id}><button type="button" disabled={mutationDisabled} onClick={() => props.chooseSong(record)}>{record.displayNumber} · {record.title} ({record.language})</button></li>)}</ul>
        {s.selectedSong && <p>Selected target: <strong>{s.selectedSong.displayNumber} · {s.selectedSong.title}</strong></p>}
        {!currentSong
          ? <button type="button" disabled={!s.selectedSong || mutationDisabled} onClick={() => props.mutate(s.selectedSong!.id)}>Set recommendation</button>
          : <><button type="button" disabled={!s.selectedSong || sameSong || mutationDisabled} onClick={() => props.mutate(s.selectedSong!.id)}>Replace recommendation</button><button type="button" disabled={mutationDisabled} onClick={() => props.mutate(null)}>Remove recommendation</button></>}
        {mutation.loading && <span role="status" className="field-help">Saving…</span>}
        {mutation.error && <p role="alert" className="field-help">{mutation.error}</p>}
        {s.saved && <span role="status" className="field-help">Saved.</span>}
      </div>}
    </div>}
  </section>;
}

export function ReferenceAntiphonRecommendationPanel({ runtime, actor, clientFactories = defaultFactories }: ReferenceAntiphonRecommendationPanelProps) {
  const role = actor.role as RecommendationUiRole;
  const machineRef = useRef<ReferenceAntiphonRecommendationUiState | null>(null);
  if (!machineRef.current) machineRef.current = new ReferenceAntiphonRecommendationUiState({ runtimeMode: runtime, userId: actor.userId, role, selectedAntiphonId: null });
  const machine = machineRef.current;
  const [snapshot, setSnapshot] = useState(() => machine.snapshot());
  const [antiphonSearch, setAntiphonSearch] = useState("");
  const [songSearch, setSongSearch] = useState("");
  const clients = useMemo(() => createRecommendationPanelClients(runtime, actor, clientFactories), [runtime, actor.userId, actor.role, clientFactories]);
  const sync = () => setSnapshot(machine.snapshot());

  useEffect(() => {
    const changed = machine.changeRuntimeActor(runtime, actor.userId, role);
    if (changed) setSongSearch("");
    if (runtime === "memory") setAntiphonSearch("");
    sync();
  }, [runtime, actor.userId, actor.role]);
  useEffect(() => {
    if (!clients) return;
    const query = antiphonSearch.trim();
    if (!query) { machine.cancel("antiphonSearch", { antiphons: [] }); sync(); return; }
    const token = machine.begin("antiphonSearch"); sync();
    void clients.antiphons.list({ language: "all", search: query, page: 0, pageSize: 25 }).then((page) => { if (machine.complete(token, { antiphons: page.records })) sync(); }).catch((cause: unknown) => { if (machine.fail(token, cause instanceof Error ? cause.message : "Antiphon search failed.")) sync(); });
  }, [clients, antiphonSearch]);
  useEffect(() => {
    const selected = snapshot.selectedAntiphon;
    if (!clients || !selected) return;
    const token = machine.begin("recommendationRead"); sync();
    void clients.recommendations.get(selected.id).then((result) => {
      if (result.success ? machine.complete(token, { recommendation: result.value }) : machine.fail(token, result.error.message)) sync();
    }).catch((cause: unknown) => { if (machine.fail(token, cause instanceof Error ? cause.message : "Recommendation load failed.")) sync(); });
  }, [clients, snapshot.selectedAntiphon?.id, actor.userId, actor.role]);
  useEffect(() => {
    if (!clients || role !== "admin" || !snapshot.selectedAntiphon) return;
    const query = songSearch.trim();
    if (!query) { machine.cancel("songSearch", { songs: [] }); sync(); return; }
    const token = machine.begin("songSearch"); sync();
    void clients.catalog.list({ language: "all", search: query, page: 0, pageSize: 25 }).then((page) => { if (machine.complete(token, { songs: page.records })) sync(); }).catch((cause: unknown) => { if (machine.fail(token, cause instanceof Error ? cause.message : "Reference song search failed.")) sync(); });
  }, [clients, role, snapshot.selectedAntiphon?.id, songSearch]);

  const chooseAntiphon = (record: ReferenceAntiphonRecord) => { machine.selectAntiphon(record); setSongSearch(""); sync(); };
  const deselectAntiphon = () => { machine.selectAntiphon(null); setSongSearch(""); sync(); };
  const chooseSong = (record: ReferenceCatalogRecord) => { machine.selectSong(record); sync(); };
  const mutate = async (referenceSongId: string | null) => {
    const selected = machine.snapshot().selectedAntiphon;
    if (!clients || role !== "admin" || !selected) return;
    const token = machine.begin("mutation"); sync();
    try {
      const result = await clients.recommendations.set(selected.id, referenceSongId);
      if (result.success) { if (machine.mutationSucceeded(token, result.value)) { setSongSearch(""); sync(); } }
      else if (machine.fail(token, result.error.message)) sync();
    } catch (cause) { if (machine.fail(token, cause instanceof Error ? cause.message : "Recommendation save failed.")) sync(); }
  };

  return <ReferenceAntiphonRecommendationPanelView runtime={runtime} role={role} snapshot={snapshot} antiphonSearch={antiphonSearch} songSearch={songSearch} setAntiphonSearch={setAntiphonSearch} setSongSearch={setSongSearch} chooseAntiphon={chooseAntiphon} deselectAntiphon={deselectAntiphon} chooseSong={chooseSong} mutate={(id) => void mutate(id)} />;
}
